style.css:
@-moz-document domain("ome.tv") {
/* Main Background & Text Color Override */
    html, body, #app, .main-layout, [class*="layout"], [class*="wrapper"] {
        background-color: #121212 !important;
        color: #e0e0e0 !important;
    }

    /* Video Container Wrappers */
    .video-container, .remote-video, .local-video, [id*="video"], [class*="video-pane"] {
        background-color: #000000 !important;
        border-color: #2c2c2c !important;
    }

    /* Chat Area & Message Boxes */
    .chat-box, .messages-container, .conversation, [class*="chat"] {
        background-color: #1a1a1a !important;
        color: #ffffff !important;
        border-color: #333333 !important;
    }

    /* Text Inputs and Chat Entry Bars */
    textarea, input[type="text"], .message-input, [class*="input"] {
        background-color: #242424 !important;
        color: #ffffff !important;
        border: 1px solid #444444 !important;
    }

    /* Navigation Bars, Sidebars, and Headers */
    header, footer, .navigation, .sidebar, .panel, [class*="header"], [class*="bar"] {
        background-color: #1c1c1c !important;
        border-color: #2d2d2d !important;
    }

    /* Control Buttons (Next, Stop, Settings) */
    button, .btn, [class*="button"], [class*="control"] {
        background-color: #2a2a2a !important;
        color: #ffffff !important;
        border: 1px solid #444444 !important;
        transition: background-color 0.2s ease !important;
    }

    /* Button Hover and Active States */
    button:hover, .btn:hover, [class*="button"]:hover {
        background-color: #3a3a3a !important;
        border-color: #555555 !important;
    }

    /* Dialog boxes / Modals / Popups */
    .modal, .dialog, .popup, [class*="modal"], [class*="popup"] {
        background-color: #1e1e1e !important;
        color: #ffffff !important;
        border: 1px solid #3a3a3a !important;
        box-shadow: 0 4px 20px rgba(0, 0, 0, 0.8) !important;
    }

    /* Text formatting fixes to prevent dark-on-dark text */
    span, p, h1, h2, h3, div {
        text-shadow: none !important;
    }
}
